21	/// Borrow block `b` of `img`. `None` past the end of the image.
22	pub fn block(img: &[u8], b: u32) -> Option<&[u8]> {
23	    let start = (b as usize).checked_mul(MFS_BLOCK_SIZE)?;
24	    img.get(start..start.checked_add(MFS_BLOCK_SIZE)?)
25	}
26	
27	/// Decode the superblock. `None` if the image is too short or the superblock is
28	/// not a MinixFS v3 this build reads.
29	pub fn superblock(img: &[u8]) -> Option<Superblock> {
30	    let sb = Superblock::from_le_bytes(img.get(SUPER_OFFSET..SUPER_OFFSET + SUPER_ON_DISK_LEN)?)?;
31	    sb.validate().ok()?;
32	    Some(sb)
33	}
34	
35	/// The image's layout, derived from its own superblock.
36	pub fn image_layout(img: &[u8]) -> Option<Layout> {
37	    let sb = superblock(img)?;
38	    Some(layout(sb.ninodes, sb.zones, MFS_BLOCK_SIZE))
39	}
40	
41	/// Fetch inode `ino`.
42	pub fn inode(img: &[u8], ino: u32) -> Option<Inode> {
43	    let l = image_layout(img)?;
44	    let (b, slot) = inode_location(ino, &l, MFS_BLOCK_SIZE)?;
45	    inode_at(block(img, b)?, slot)
46	}
47	
48	/// Read a file's (or directory's) contents, honouring holes.
49	///
50	/// A hole reads as zeroes — that is what a hole *means* — while an offset past
51	/// what the format can address is `None`, never silent zeroes. That distinction is
52	/// the reason `zone_for_offset` has both a `Hole` and an `OutOfRange`.
53	pub fn read_inode_bytes(img: &[u8], ino: &Inode) -> Option<Vec<u8>> {
54	    let size = usize::try_from(ino.size).ok()?;
55	    let mut out = Vec::with_capacity(size);
56	    let mut off = 0usize;
57	    while off < size {
58	        let want = (size - off).min(MFS_BLOCK_SIZE);
59	        match zone_for_offset(ino, off as u64, MFS_BLOCK_SIZE) {
60	            ZoneLookup::Direct(z) => out.extend_from_slice(&block(img, z)?[..want]),
61	            ZoneLookup::Indirect { zone, slot } => {
62	                let z = zone_from_indirect(block(img, zone)?, slot)?;
63	                if z == 0 {
64	                    out.extend(std::iter::repeat_n(0u8, want));
65	                } else {
66	                    out.extend_from_slice(&block(img, z)?[..want]);
67	                }
68	            }
69	            ZoneLookup::Hole => out.extend(std::iter::repeat_n(0u8, want)),
70	            ZoneLookup::OutOfRange => return None,
71	        }
72	        off += want;
73	    }
74	    Some(out)
75	}
76	
77	/// Resolve an absolute path to `(inode number, inode)`.
78	///
79	/// `"/"` is the root. Each component is looked up through the directory's own
80	/// entries, so a path that names a file as an intermediate component fails rather
81	/// than reading a file's bytes as directory entries.
82	pub fn lookup(img: &[u8], path: &str) -> Option<(u32, Inode)> {
83	    let mut ino = ROOT_INODE;
84	    let mut node = inode(img, ino)?;
85	    for component in path.split('/').filter(|c| !c.is_empty()) {
86	        if !node.is_dir() {
87	            return None;
88	        }
89	        let bytes = read_inode_bytes(img, &node)?;
90	        ino = bytes
91	            .chunks(MFS_BLOCK_SIZE)
92	            .flat_map(iter_block)
93	            .find(|e| e.name_str() == component)
94	            .map(|e| e.ino)?;
95	        node = inode(img, ino)?;
96	    }
97	    Some((ino, node))
98	}
99	
100	/// Read a regular file's contents by path.
101	pub fn read_file(img: &[u8], path: &str) -> Option<Vec<u8>> {
102	    let (_, node) = lookup(img, path)?;
103	    if !node.is_reg() {
104	        return None;
105	    }
106	    read_inode_bytes(img, &node)
107	}
108	
109	/// List a directory's entry names by path, in on-disk order (so `.` and `..`
110	/// come first).
111	pub fn read_dir(img: &[u8], path: &str) -> Option<Vec<String>> {
112	    let (_, node) = lookup(img, path)?;
113	    if !node.is_dir() {
114	        return None;
115	    }
116	    let bytes = read_inode_bytes(img, &node)?;
117	    Some(
118	        bytes
119	            .chunks(MFS_BLOCK_SIZE)
120	            .flat_map(iter_block)
121	            .map(|e| e.name_str().to_string())
122	            .collect(),
123	    )
124	}
125	
126	/// Is inode `ino` marked allocated in the inode bitmap?
127	pub fn imap_bit_set(img: &[u8], ino: u32) -> Option<bool> {
128	    let l = image_layout(img)?;
129	    bit_set(img, l.imap_start, imap_bit(ino))
130	}
131	
132	/// Is zone `zone` marked allocated in the zone bitmap? `None` for a zone below
133	/// the first data zone, which has no bit.
134	pub fn zmap_bit_set(img: &[u8], zone: u32) -> Option<bool> {
135	    let l = image_layout(img)?;
136	    bit_set(img, l.zmap_start, zmap_bit(zone, l.first_data_zone)?)
137	}
138	
139	fn bit_set(img: &[u8], start: u32, bit: u32) -> Option<bool> {
140	    let byte = (start as usize).checked_mul(MFS_BLOCK_SIZE)? + (bit as usize) / 8;
141	    Some(img.get(byte)? & (1 << (bit % 8)) != 0)
142	}
