68	/// ELF entry point. The kernel primes `SP_EL0` before `eret`, so `_start` can dive
69	/// straight into Rust without setting up a stack itself.
70	// Gate the whole shim to `not(test)`: under `cargo test` the crate links as a
71	// normal host executable, and an exported `_start` would collide with the C
72	// runtime's. `.text._start` is an ELF section name, gated to the minixrs target
73	// so `cargo check --workspace` on a Mach-O host still type-checks.
74	#[cfg(not(test))]
75	#[unsafe(no_mangle)]
76	#[cfg_attr(target_os = "minixrs", unsafe(link_section = ".text._start"))]
77	pub extern "C" fn _start() -> ! {
78	    main()
79	}
80	
81	// Only `_start` calls `main`; under `cargo test` `_start` is gone, so `main` (and
82	// the helpers it alone reaches) would read as dead code.
83	#[cfg_attr(test, allow(dead_code))]
84	fn main() -> ! {
85	    let sef = sef_startup(SefConfig {
86	        init_fresh: Some(mem_init),
87	        signal_handler: None,
88	    })
89	    .unwrap_or_else(|_| {
90	        // No recovery and nothing to print: a failed handshake means this driver
91	        // never learned its own endpoint, so it cannot even announce the failure.
92	        loop {
93	            core::hint::spin_loop()
94	        }
95	    });
96	
97	    // Where the ramdisk is, and how big. Locals in `main`'s frame — not statics,
98	    // and not `mem_init`'s frame, whose stack is gone by the time a client calls —
99	    // the same rule `GrantPool` and TTY's staging buffer follow.
100	    //
101	    // Deliberately *after* `sef_startup` rather than inside `mem_init`: the kernel
102	    // gates `GET_RAMDISK` on the caller's proc number, so a failure here means the
103	    // kernel's pre-map arm and its getinfo gate disagree — worth its own diag line
104	    // and a degraded-but-alive driver, not an aborted startup that also takes the
105	    // `sef ready` marker with it.
106	    let (va, blocks) = ramdisk_geometry();
107	
108	    let mut msg = Message {
109	        m_source: 0,
110	        m_type: 0,
111	        payload: [0u8; 96],
112	    };
113	    loop {
114	        if sef.receive(&mut msg) != OK {
115	            continue;
116	        }
117	        // Capture the caller *first*: it is both the reply target and the granter,
118	        // and the dispatch below overwrites `msg.m_source` on the way out.
119	        let caller_e = msg.m_source;
120	        match msg.m_type {
121	            BDEV_READ => {
122	                let rc = do_read(caller_e, &msg, va, blocks);
123	                reply(caller_e, &mut msg, rc);
124	            }
125	            // Defined and refused, rather than folded into the `_` arm below —
126	            // that difference is the whole reason `BDEV_WRITE` has a number.
127	            BDEV_WRITE => {
128	                let rc = do_write(&msg, blocks);
129	                reply(caller_e, &mut msg, rc);
130	            }
131	            // Unlike DS, reply rather than drop — the caller is inside a SENDREC
132	            // and would otherwise block forever.
133	            _ => reply(caller_e, &mut msg, ENOSYS),
134	        }
135	    }
136	}
137	
138	/// SEF fresh-init callback: publish to DS. Nothing else — see [`ramdisk_geometry`]
139	/// for why the ramdisk lookup happens in `main`'s frame instead.
140	#[cfg_attr(test, allow(dead_code))]
141	fn mem_init(_endpoint: Endpoint, name: &[u8; SYS_GETINFO_NAME_LEN]) -> i32 {
142	    sef_publish_to_ds(name)
143	}
144	
145	/// Ask the kernel where the ramdisk is, check it over, and announce the result.
146	///
147	/// Returns `(va, blocks)`. On any failure `blocks` is `0`, which makes every
148	/// subsequent `BDEV_READ` fail its range check with `EINVAL` rather than letting a
149	/// bad geometry reach `SYS_SAFECOPY`. A zero-block device is exactly the right
150	/// degenerate state: clients hear "out of range" for every block, and the driver
151	/// still answers every request.
152	#[cfg_attr(test, allow(dead_code))]
153	fn ramdisk_geometry() -> (u64, u64) {
154	    let mut msg = Message {
155	        m_source: 0,
156	        m_type: 0,
157	        payload: [0u8; 96],
158	    };
159	    let rc = sys_getinfo(GET_RAMDISK, &mut msg);
160	    if rc != OK {
161	        diag_fmt(format_args!("ramdisk FAIL getinfo rc={rc}"));
162	        return (RAMDISK_VA, 0);
163	    }
164	    let va = rd_u64(&msg, GETINFO_RAMDISK_VA_OFF);
165	    let len = rd_u64(&msg, GETINFO_RAMDISK_LEN_OFF);
166	
167	    let blocks = match bdev::validate_geometry(len) {
168	        Ok(blocks) => blocks,
169	        Err(e) => {
170	            diag_fmt(format_args!("ramdisk FAIL geometry len={len} rc={e}"));
171	            return (va, 0);
172	        }
173	    };
174	    if selfcheck(va, len, blocks) {
175	        (va, blocks)
176	    } else {
177	        (va, 0)
178	    }
179	}
180	
181	/// Prove the mapping is real, complete, and holds the image this build packed.
182	///
183	/// Two 32-byte reads through `SYS_COPY(SELF → SELF)`, which the kernel supports:
184	/// `do_copy` short-circuits `SELF` for both endpoints, and `copy_between_as` over
185	/// two disjoint ranges of one address space is an ordinary copy. Going through a
186	/// kernel call rather than dereferencing is what keeps this crate free of `unsafe`
187	/// blocks and turns an unmapped page into an errno instead of a fault.
188	///
189	/// The **head** read checks the image label and cross-checks the header's own
190	/// block count against the length the kernel reported — binding mkfs's geometry to
191	/// the kernel's copy, two independently derived numbers.
192	///
193	/// The **tail** read is the one that earns its keep. It reads the reserved last
194	/// block, whose label deliberately differs from the header's, so a kernel copy
195	/// loop that failed to advance — mapping 256 pages of block 0 — fails here while
196	/// every header check still passes. Nothing else in the boot proves the copy
197	/// reached the end of the blob.
198	///
199	/// Deliberately a *device*-level check: no superblock is decoded and
200	/// `minixrs-mfs` is not a dependency, because a block driver must not depend on
201	/// the filesystem format. `tools/mkfs-mfs`'s round trip is what proves the header
202	/// cannot disagree with the real superblock.
203	#[cfg_attr(test, allow(dead_code))]
204	fn selfcheck(va: u64, len: u64, blocks: u64) -> bool {
205	    let mut buf = [0u8; IMAGE_HDR_LEN];
206	
207	    let rc = sys_copy(SELF, va, SELF, buf_addr(&mut buf), IMAGE_HDR_LEN as u64);
208	    if rc != OK {
209	        diag_fmt(format_args!("ramdisk FAIL head rc={rc}"));
210	        return false;
211	    }
212	    if buf[..IMAGE_LABEL_LEN] != IMAGE_LABEL {
213	        diag_fmt(format_args!("ramdisk FAIL label"));
214	        return false;
215	    }
216	    let hdr_blocks = rd_hdr_u32(&buf, HDR_BLOCKS_OFF);
217	    if u64::from(hdr_blocks) != blocks {
218	        diag_fmt(format_args!(
219	            "ramdisk FAIL blocks hdr={hdr_blocks} dev={blocks}"
220	        ));
221	        return false;
222	    }
223	
224	    // `len` is non-zero and a whole number of blocks (`validate_geometry`), so this
225	    // cannot underflow and names the last block's first byte.
226	    let tail_va = va + len - BDEV_BLOCK_SIZE as u64;
227	    let rc = sys_copy(
228	        SELF,
229	        tail_va,
230	        SELF,
231	        buf_addr(&mut buf),
232	        IMAGE_HDR_LEN as u64,
233	    );
234	    if rc != OK {
235	        diag_fmt(format_args!("ramdisk FAIL tail rc={rc}"));
236	        return false;
237	    }
238	    if buf[..IMAGE_LABEL_LEN] != IMAGE_TAIL_LABEL {
239	        diag_fmt(format_args!("ramdisk FAIL tail label"));
240	        return false;
241	    }
242	
243	    diag_fmt(format_args!("ramdisk ok blocks={blocks} tail=1"));
244	    true
245	}
246	
247	/// Read a little-endian `u32` out of the image header.
248	///
249	/// `from_le_bytes` rather than one of `server-rt`'s payload accessors: those
250	/// describe *message* fields, which are native-endian by construction because the
251	/// kernel copies them between two processes on the same machine. This is an
252	/// on-disk image written by a build host, so it is explicitly little-endian — the
253	/// same assumption the MXBI archive already makes.
254	fn rd_hdr_u32(buf: &[u8; IMAGE_HDR_LEN], off: usize) -> u32 {
255	    u32::from_le_bytes([buf[off], buf[off + 1], buf[off + 2], buf[off + 3]])
256	}
257	
258	/// Serve one `BDEV_READ`. Returns the reply `m_type`: the byte count read
259	/// (`>= 0`), or a negative errno.
260	#[cfg_attr(test, allow(dead_code))]
261	fn do_read(caller_e: Endpoint, msg: &Message, va: u64, blocks: u64) -> i32 {
262	    let req = bdev::parse_read(msg);
263	    let (byte_off, n) = match bdev::validate_read(req, blocks) {
264	        Ok(v) => v,
265	        Err(e) => return e,
266	    };
267	    if n == 0 {
268	        // A legal zero-length read. No grant is used and nothing is copied, so a
269	        // client polling with `len = 0` cannot use it to probe a grant.
270	        return 0;
271	    }
272	
273	    // Push the bytes into the client's granted buffer. `caller_e` is the
274	    // kernel-stamped source of this very message — the granter can be nothing else.
275	    //
276	    // The grant offset is `0`, not a payload field: `BDEV_READ` deliberately has
277	    // none, because every client through slice 5.9 grants a buffer whose block
278	    // starts at its beginning.
279	    let rc = sys_safecopy(SAFECOPY_TO, caller_e, req.gid, 0, va + byte_off, n as u64);
280	    if rc != OK {
281	        // Verbatim: EPERM ("your grant does not authorize this") and EFAULT ("your
282	        // buffer is not mapped") are different bugs on the client's side.
283	        return rc;
284	    }
285	    n as i32
286	}
287	
288	/// Refuse one `BDEV_WRITE`, but only after checking the request is one this device
289	/// could have served. Returns the reply `m_type`: always negative.
290	///
291	/// **Validation precedes the refusal on purpose.** A write to minor 7 should hear
292	/// `ENXIO` ("no such device"), not `EROFS` ("that device is read-only") — the
293	/// latter asserts something about a device that does not exist, and it is the
294	/// same check-order discipline `validate_read` documents: each check is the first
295	/// thing that can be wrong given the ones before it.
296	///
297	/// It is also what makes the claim in this module's docs true. Slice 5.10 turns
298	/// this into a real write by replacing the `EROFS` below with the store; if the
299	/// validation were not already here, 5.10 would have to *add* it, and "one line
300	/// inside one arm" would have been an overstatement.
301	///
302	/// The payload and every check are shared with `BDEV_READ` — see `ReadRequest`,
303	/// whose name is the only thing about it that is read-specific. The one field
304	/// that will differ in 5.10 is the grant's access bit (`CPF_READ` rather than
305	/// `CPF_WRITE`), which the kernel checks, not this driver.
306	#[cfg_attr(test, allow(dead_code))]
307	fn do_write(msg: &Message, blocks: u64) -> i32 {
308	    let req = bdev::parse_read(msg);
309	    match bdev::validate_read(req, blocks) {
310	        Ok(_) => EROFS,
311	        Err(e) => e,
312	    }
313	}
314	
315	/// Reply to a SENDREC caller: stamp `m_type`, zero `m_source` (the kernel
316	/// overwrites it on delivery), and SEND the message back. A copy of TTY's, for the
317	/// reason TTY's exists.
318	#[cfg_attr(test, allow(dead_code))]
319	fn reply(target_e: Endpoint, msg: &mut Message, m_type: i32) {
320	    msg.m_type = m_type;
321	    msg.m_source = 0;
322	    let _ = ipc_send(target_e, msg);
323	}
324	
325	// The freestanding panic handler; under `cargo test` std supplies its own.
326	#[cfg(not(test))]
327	#[panic_handler]
328	fn panic(_: &core::panic::PanicInfo) -> ! {
329	    loop {
330	        core::hint::spin_loop()
331	    }
332	}
