3	//! The per-process file-descriptor table (slice 5.4).
4	//!
5	//! VFS's whole job is turning a small integer into a thing that can be written
6	//! to. This module is that mapping and nothing else: pure, total, and host-tested,
7	//! with the IPC glue in `main.rs` — the `servers/ds` `registry.rs` / `main.rs`
8	//! split.
9	//!
10	//! ## Every process starts with the same three descriptors
11	//!
12	//! There is no `open` yet (slice 5.8), so the table is *entirely* determined at
13	//! compile time: fds 0, 1, and 2 name the console character device in every row,
14	//! and nothing else is open. That is the POSIX convention — a process inherits
15	//! stdin/stdout/stderr rather than opening them — and it is what lets init write
16	//! a banner without a filesystem existing.
17	//!
18	//! Because nothing mutates, the storage is an ordinary **immutable `static`** and
19	//! this crate carries no `unsafe` at all. Slice 5.8's `open`/`close` flips it to
20	//! the `UnsafeCell<[FdRow; N]>` + `unsafe impl Sync` newtype that
21	//! `servers/vm/src/region.rs` and `servers/ds/src/registry.rs` already use, under
22	//! the same single-mutator invariant (VFS is one EL0 thread running a
23	//! straight-line receive loop, with no interrupt handlers of its own). Nothing
24	//! else about the module changes: [`resolve_in`] already takes the rows as a
25	//! borrowed slice precisely so it stays pure across that switch.
26	
27	use minixrs_kernel_shared::callnr::CDEV_MINOR_CONSOLE;
28	use minixrs_kernel_shared::com::NR_SERVED_PROCS;
29	use minixrs_kernel_shared::error::EBADF;
30	
31	/// Descriptors per process. Three are pre-opened (stdin/stdout/stderr) and the
32	/// fourth exists so "past the end of the row" is reachable in a test without
33	/// being the same case as "not open". VFS-local, deliberately **not** part of the
34	/// ABI: a client learns a descriptor is bad from `EBADF`, never from arithmetic
35	/// on a published constant. Slice 5.8 raises it.
36	pub const NR_FDS: usize = 4;
37	
38	/// What a descriptor refers to.
39	///
40	/// One variant today. Slice 5.8's `open` adds the regular-file variant (an inode
41	/// on a mounted MFS plus a seek offset), at which point `do_write`'s `match` on
42	/// this enum is what routes a write to a driver or to the filesystem.
43	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
44	pub enum Fd {
45	    /// Not open. Every operation on it is `EBADF`.
46	    Unused,
47	    /// A character device — today only the console, via `CDEV_WRITE` to TTY.
48	    CharDev {
49	        /// Device minor, e.g. [`CDEV_MINOR_CONSOLE`]. Passed through to the
50	        /// driver, which is the one that decides whether it exists (`ENXIO`).
51	        minor: i32,
52	    },
53	}
54	
55	/// One process's descriptors, indexed by descriptor number.
56	pub type FdRow = [Fd; NR_FDS];
57	
58	/// The descriptors every process is born with: 0, 1, and 2 on the console.
59	const DEFAULT_ROW: FdRow = [
60	    Fd::CharDev {
61	        minor: CDEV_MINOR_CONSOLE,
62	    },
63	    Fd::CharDev {
64	        minor: CDEV_MINOR_CONSOLE,
65	    },
66	    Fd::CharDev {
67	        minor: CDEV_MINOR_CONSOLE,
68	    },
69	    Fd::Unused,
70	];
71	
72	/// Rows in the table — one per process, indexed by **kernel proc number**.
73	///
74	/// Sized from [`NR_SERVED_PROCS`], the single shared ceiling PM's `mproc`, VM's
75	/// `ClientRegions`, and SCHED's policy table all derive from, so a process that
76	/// exists to one server is addressable in all of them. Never reintroduce an
77	/// independent capacity literal here: the guard below is what makes an
78	/// under-sized edit a compile error rather than a runtime `EBADF` that only the
79	/// highest-numbered processes ever see. Same shape as VM's `MAX_CLIENTS`.
80	const NR_FD_ROWS: usize = NR_SERVED_PROCS;
81	
82	const _: () = assert!(NR_FD_ROWS >= NR_SERVED_PROCS);
83	
84	/// The table itself. Immutable until slice 5.8's `open` — see the module note.
85	static ROWS: [FdRow; NR_FD_ROWS] = [DEFAULT_ROW; NR_FD_ROWS];
86	
87	/// Resolve `(proc_nr, fd)` against a borrowed table.
88	///
89	/// The pure half — `rows` is passed in so this is testable without touching the
90	/// static, and so it survives slice 5.8's switch to interior-mutable storage
91	/// unchanged.
92	///
93	/// `EBADF` for every way of naming nothing: a negative descriptor, one past the
94	/// end of the row, a descriptor that is not open, and a proc number outside the
95	/// table. The last of those is the interesting one — it is how a message from a
96	/// process VFS has no row for (a proc number beyond `NR_SERVED_PROCS`, or the
97	/// negative number of a kernel task) fails closed rather than indexing wild.
98	pub fn resolve_in(rows: &[FdRow], proc_nr: i32, fd: i32) -> Result<Fd, i32> {
99	    let Ok(slot) = usize::try_from(proc_nr) else {
100	        return Err(EBADF);
101	    };
102	    let Ok(idx) = usize::try_from(fd) else {
103	        return Err(EBADF);
104	    };
105	    match rows.get(slot).and_then(|row| row.get(idx)) {
106	        Some(Fd::Unused) | None => Err(EBADF),
107	        Some(open) => Ok(*open),
108	    }
109	}
110	
111	/// Resolve `(proc_nr, fd)` against the live table. The thin wrapper the receive
112	/// loop calls; all the logic is in [`resolve_in`].
113	pub fn resolve(proc_nr: i32, fd: i32) -> Result<Fd, i32> {
114	    resolve_in(&ROWS, proc_nr, fd)
115	}
116	
117	#[cfg(test)]
118	mod tests {
119	    use super::*;
120	
121	    const CONSOLE: Fd = Fd::CharDev {
122	        minor: CDEV_MINOR_CONSOLE,
123	    };
124	
125	    #[test]
126	    fn stdin_stdout_and_stderr_are_the_console_for_every_process() {
127	        // The pre-open contract, checked across the whole proc-number range
128	        // rather than for one process: init, a boot server, and a forked child
129	        // must all find fd 1 without anything having opened it.
130	        for proc_nr in 0..NR_SERVED_PROCS as i32 {
131	            for fd in 0..3 {
132	                assert_eq!(resolve(proc_nr, fd), Ok(CONSOLE), "proc {proc_nr} fd {fd}");
133	            }
134	        }
135	    }
136	
137	    #[test]
138	    fn every_row_is_identical_today() {
139	        // Slice 5.8's `open` is what makes rows diverge. Stating the invariant
140	        // now means that change shows up here as a deliberate edit rather than
141	        // silently invalidating the loop above.
142	        for row in ROWS.iter() {
143	            assert_eq!(*row, DEFAULT_ROW);
144	        }
145	    }
146	
147	    #[test]
148	    fn an_unopened_descriptor_is_ebadf() {
149	        // fd 3 exists in the row but holds `Unused` — the case that proves
150	        // "in range" and "open" are separate questions.
151	        assert_eq!(ROWS[0][3], Fd::Unused);
152	        assert_eq!(resolve(0, 3), Err(EBADF));
153	    }
154	
155	    #[test]
156	    fn a_descriptor_past_the_end_of_the_row_is_ebadf() {
157	        for fd in [NR_FDS as i32, NR_FDS as i32 + 1, 64, i32::MAX] {
158	            assert_eq!(resolve(0, fd), Err(EBADF), "fd {fd}");
159	        }
160	    }
161	
162	    #[test]
163	    fn a_negative_descriptor_is_ebadf() {
164	        // A client that passed through an errno by mistake, or a wrapped count.
165	        for fd in [-1i32, -3, i32::MIN] {
166	            assert_eq!(resolve(0, fd), Err(EBADF), "fd {fd}");
167	        }
168	    }
169	
170	    #[test]
171	    fn a_proc_number_outside_the_table_is_ebadf() {
172	        // Above the ceiling, and the negative numbers kernel tasks carry —
173	        // neither may index the table, and neither may panic.
174	        for proc_nr in [
175	            NR_SERVED_PROCS as i32,
176	            NR_SERVED_PROCS as i32 + 1,
177	            -1,
178	            -2,
179	            i32::MIN,
180	            i32::MAX,
181	        ] {
182	            assert_eq!(resolve(proc_nr, 1), Err(EBADF), "proc {proc_nr}");
183	        }
184	    }
185	
186	    #[test]
187	    fn resolve_in_reads_the_row_it_is_given() {
188	        // The pure helper must not reach the static: hand it a table whose fd 1
189	        // is closed and whose fd 3 is open, the opposite of the real one.
190	        let mut rows = [DEFAULT_ROW; 2];
191	        rows[1][1] = Fd::Unused;
192	        rows[1][3] = Fd::CharDev { minor: 7 };
193	
194	        assert_eq!(resolve_in(&rows, 0, 1), Ok(CONSOLE));
195	        assert_eq!(resolve_in(&rows, 1, 1), Err(EBADF));
196	        assert_eq!(resolve_in(&rows, 1, 3), Ok(Fd::CharDev { minor: 7 }));
197	        // ...and the static is unchanged, so the two really are independent.
198	        assert_eq!(resolve(1, 1), Ok(CONSOLE));
199	    }
200	
201	    #[test]
202	    fn an_empty_table_resolves_nothing() {
203	        // Degenerate borrow: no rows at all. `resolve_in` must answer `EBADF`
204	        // rather than index into a zero-length slice.
205	        assert_eq!(resolve_in(&[], 0, 1), Err(EBADF));
206	    }
207	}
