3	//! `VFS_WRITE` request parsing, validation, and the short-write loop's policy.
4	//!
5	//! Everything here is a total function over plain values, so it carries the
6	//! crate's unit tests; the IPC round-trip lives in `main.rs` and is verified
7	//! through the boot log. Same split as `drivers/tty`'s `cdev.rs` / `main.rs` and
8	//! `servers/ds`'s `registry.rs` / `main.rs`.
9	//!
10	//! ## Why the loop is a step function
11	//!
12	//! [`advance`] holds the whole of what makes a short-write loop correct — when to
13	//! stop, what to report, and what to do about a driver that answers implausibly —
14	//! with the SENDREC lifted out. That is what makes those rules testable at all: in
15	//! the loop itself they are only reachable through a live TTY, so a driver that
16	//! reported `0`, or more bytes than it was asked for, could not be exercised
17	//! without breaking the driver. Here they are three lines of test each.
18	//!
19	//! ## Where the length rules live, and where they don't
20	//!
21	//! [`validate`] owns the `len`/`buf` checks; the descriptor is `fd.rs`'s business
22	//! and is resolved separately by the caller. The two are deliberately not merged:
23	//! a descriptor is looked up in per-process state, a length is judged on its own,
24	//! and only the first will grow a mount table under it in slice 5.8.
25	
26	use minixrs_kernel_shared::Message;
27	use minixrs_kernel_shared::callnr::{VFS_BUF_OFF, VFS_FD_OFF, VFS_LEN_OFF};
28	use minixrs_kernel_shared::error::{EFAULT, EINVAL};
29	use minixrs_kernel_shared::message::user_range_ok;
30	use minixrs_server_rt::{rd_i32, rd_u64};
31	
32	/// A parsed `VFS_WRITE` request. Field-for-field the payload, with no
33	/// interpretation applied — [`validate`] and `fd::resolve` do that.
34	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
35	pub struct WriteRequest {
36	    /// The descriptor to write to. Resolved against the caller's fd row.
37	    pub fd: i32,
38	    /// Bytes the caller asked to write.
39	    pub len: i32,
40	    /// The buffer's address **in the caller's own address space**. Not a grant
41	    /// id: the caller is an ordinary user process with no grant table, and VFS is
42	    /// what turns this into a magic grant naming the caller as owner.
43	    pub buf: u64,
44	}
45	
46	/// Read a `VFS_WRITE` request out of a message payload.
47	///
48	/// Total: every field is a fixed-offset scalar read that cannot fail
49	/// (`server-rt`'s accessors return `0` for an out-of-range offset), so a
50	/// malformed request becomes an invalid *value* that the checks reject, never a
51	/// panic.
52	pub fn parse(msg: &Message) -> WriteRequest {
53	    WriteRequest {
54	        fd: rd_i32(msg, VFS_FD_OFF),
55	        len: rd_i32(msg, VFS_LEN_OFF),
56	        buf: rd_u64(msg, VFS_BUF_OFF),
57	    }
58	}
59	
60	/// Decide how many bytes this request is asking for, or which errno to reply.
61	///
62	/// `Ok(0)` is a legal empty write, not an error — and it is checked **before**
63	/// the buffer, so a caller writing zero bytes is never asked to supply a valid
64	/// pointer (POSIX does not require one) and no grant is issued for it. That last
65	/// part matters: a zero-length write must not be usable to probe the granting
66	/// path, which is the rule TTY applies one layer down.
67	///
68	/// The checks, in order:
69	///
70	/// 1. `len < 0` → `EINVAL`. Left unchecked it would widen into a ~16 EiB `u64`
71	///    byte count on the grant.
72	/// 2. `len == 0` → `Ok(0)`.
73	/// 3. The buffer must lie in the user address range — `user_range_ok`, the
74	///    no-alignment variant grants use, since a `write()` buffer is a byte buffer.
75	///    This is **defence in depth, not the load-bearing gate**: the kernel's copy
76	///    engine walks the caller's page tables and answers `EFAULT` for anything
77	///    unmapped regardless (D5). It stays because rejecting a malformed pointer
78	///    before issuing a grant is cheaper and more legible than discovering it two
79	///    hops away.
80	pub fn validate(len: i32, buf: u64) -> Result<usize, i32> {
81	    if len < 0 {
82	        return Err(EINVAL);
83	    }
84	    let len = len as usize;
85	    if len == 0 {
86	        return Ok(0);
87	    }
88	    if !user_range_ok(buf, len as u64) {
89	        return Err(EFAULT);
90	    }
91	    Ok(len)
92	}
93	
94	/// What the short-write loop should do after one `CDEV_WRITE` reply.
95	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
96	pub enum Step {
97	    /// Send again from this offset. Only produced while there are bytes left.
98	    More(usize),
99	    /// Stop; this is the reply to the client.
100	    Done(i32),
101	}
102	
103	/// Fold one driver reply `n` into a write that has already moved `off` of `len`
104	/// bytes.
105	///
106	/// A character driver may write fewer bytes than asked (`CDEV_MAX_IO`), which is
107	/// how it stages through a small buffer with no allocator. That is a *driver*
108	/// detail and POSIX `write()` may not expose it, so the caller re-sends with
109	/// `offset` advanced. One grant covers the whole buffer; only the offset moves.
110	///
111	/// Four rules, in the order they are applied:
112	///
113	/// 1. **An error after partial progress reports the progress.** POSIX's rule: the
114	///    bytes really did go out, and telling the caller otherwise makes it send them
115	///    twice. The error resurfaces on the next write, where it is still true. With
116	///    no progress, the error is the reply.
117	/// 2. **A driver reporting zero ends the write.** No progress means re-sending the
118	///    same request forever, and a server that spins is worse than a short write.
119	/// 3. **The offset is clamped to `len`.** A driver reporting *more* than it was
120	///    asked for would otherwise walk past the buffer and over-report the write.
121	///    TTY is trusted today, but this is the shape every future block/FS client
122	///    copies, and a count is the one thing a client acts on unconditionally.
123	/// 4. Otherwise: done when the buffer is out, else go round again.
124	pub fn advance(off: usize, len: usize, n: i32) -> Step {
125	    if n < 0 {
126	        return Step::Done(if off > 0 { off as i32 } else { n });
127	    }
128	    if n == 0 {
129	        return Step::Done(off as i32);
130	    }
131	    let off = off.saturating_add(n as usize).min(len);
132	    if off >= len {
133	        Step::Done(off as i32)
134	    } else {
135	        Step::More(off)
136	    }
137	}
