190	    fn a_normal_length_passes_through() {
191	        for len in [1i32, 12, CDEV_MAX_IO as i32, CDEV_MAX_IO as i32 * 4, 4096] {
192	            assert_eq!(validate(len, BUF), Ok(len as usize), "len {len}");
193	        }
