241	    #[test]
242	    fn a_short_write_asks_for_another_round() {
243	        // The core of the loop: the driver clamped, so keep going from there.
244	        assert_eq!(advance(0, 288, 256), Step::More(256));
245	        assert_eq!(advance(256, 288, 32), Step::Done(288));
246	    }
