248	    #[test]
249	    fn a_multi_round_write_reaches_exactly_len() {
250	        // Drive the whole loop the way `write_all` does, with a driver that
251	        // clamps to CDEV_MAX_IO every time.
252	        let len = CDEV_MAX_IO * 3 + 7;
253	        let mut off = 0usize;
254	        let mut rounds = 0;
255	        let total = loop {
256	            rounds += 1;
257	            assert!(rounds <= 8, "loop failed to converge");
258	            let asked = len - off;
259	            let served = asked.min(CDEV_MAX_IO) as i32;
260	            match advance(off, len, served) {
261	                Step::More(next) => {
262	                    assert!(next > off, "no forward progress");
263	                    off = next;
264	                }
265	                Step::Done(rc) => break rc,
266	            }
267	        };
268	        assert_eq!(total, len as i32);
269	        assert_eq!(rounds, 4);
270	    }
