293	    #[test]
294	    fn a_driver_reporting_more_than_asked_cannot_over_report_the_write() {
295	        // Also unreachable through TTY. Without the clamp the reply would exceed
296	        // the length the client handed over — the one number a client acts on
297	        // unconditionally.
298	        assert_eq!(advance(0, 100, 100_000), Step::Done(100));
