302	    #[test]
303	    fn the_offset_never_exceeds_len_on_any_reply() {
304	        // The clamp as a property, over the whole interesting space rather than
305	        // three chosen points.
306	        let len = 64usize;
307	        for off in 0..=len {
308	            for n in [-1i32, 0, 1, 7, 63, 64, 65, 4096, i32::MAX] {
309	                let rc = match advance(off, len, n) {
310	                    Step::More(next) => {
311	                        assert!(next < len, "More past the end: off={off} n={n}");
312	                        assert!(next > off, "More without progress: off={off} n={n}");
313	                        continue;
314	                    }
315	                    Step::Done(rc) => rc,
316	                };
317	                if rc >= 0 {
318	                    assert!(rc as usize <= len, "over-reported: off={off} n={n} rc={rc}");
319	                }
320	            }
321	        }
322	    }
