1269	    #[test]
1270	    fn vfs_write_payload_offsets_are_ordered_and_disjoint() {
1271	        // Every field the request defines, in declaration order, with its width:
1272	        // the i32 fields are 4 bytes, the u64 buffer address is 8.
1273	        //
1274	        // Unlike `CDEV_WRITE` this payload carries a raw buffer address rather
1275	        // than a grant id — VFS's client is an ordinary user process with no
1276	        // grant table. VFS makes the grant itself, naming the caller's buffer,
1277	        // and takes the owner from the kernel-stamped `m_source`. There is
1278	        // deliberately no owner/granter field here for the same reason there is
1279	        // none in `CDEV_WRITE`: VFS holds `SYS_PROC`, so a caller-supplied owner
1280	        // would aim a privileged cross-address-space copy at a third party.
1281	        let fields = [
1282	            ("fd", VFS_FD_OFF, 4),
1283	            ("len", VFS_LEN_OFF, 4),
1284	            ("buf", VFS_BUF_OFF, 8),
1285	        ];
1286	        assert_eq!(fields.len(), 3, "a VFS_WRITE payload field was added");
1287	        assert_eq!(VFS_FD_OFF, 0, "the first field must start the payload");
1288	
1289	        for pair in fields.windows(2) {
1290	            let (name, off, width) = pair[0];
1291	            let (next_name, next_off, _) = pair[1];
1292	            assert!(
1293	                off + width <= next_off,
1294	                "{name} ({off}..{}) overlaps {next_name} at {next_off}",
1295	                off + width,
1296	            );
1297	        }
1298	        let (last_name, last_off, last_width) = fields[fields.len() - 1];
1299	        assert!(
1300	            last_off + last_width <= 96,
1301	            "{last_name} runs past the 96-byte payload",
1302	        );
1303	
1304	        // The u64 field must be 8-aligned *within the message*, whose payload
1305	        // starts at byte 8 — so an even multiple of 8 here.
1306	        assert_eq!((8 + VFS_BUF_OFF) % 8, 0);
1307	    }
