3	//! The boot ramdisk image's own header — a *build-time to run-time* ABI
4	//! (slice 5.7).
5	//!
6	//! `tools/mkfs-mfs` writes these bytes at build time; the `memory` driver and
7	//! VFS's demo client read them at run time. Three different crates, none of which
8	//! may depend on the others, so the bytes live here for the same reason
9	//! [`crate::com::ROOTFS_MODULE_NAME`] does: one literal, shared, cannot drift.
10	//!
11	//! ## Why a header at all, when there is already a superblock
12	//!
13	//! Because a *block driver* must not depend on the *filesystem format*. The
14	//! `memory` driver checks that the bytes the kernel copied into its address space
15	//! are the image it expects; that is a device-level question, and answering it
16	//! with `minixrs-mfs`'s superblock decoder would give Phase 6 a dependency to
17	//! unwind when virtio-blk replaces the ramdisk under an unchanged MFS.
18	//!
19	//! So the header sits in the **boot block** — bytes `0..1024` of block 0, which
20	//! MinixFS never reads (its superblock starts at byte 1024) — and carries the
21	//! three geometry facts a driver can check without knowing what a superblock is.
22	//! `tools/mkfs-mfs`'s round-trip tests assert those three equal the real
23	//! superblock's, which is what licenses a boot marker to check the header instead.
24	//!
25	//! ## The tail label
26	//!
27	//! [`IMAGE_TAIL_LABEL`] is written into the image's **last** zone, which mkfs
28	//! reserves (its zone-bitmap bit is set, so no file can be allocated there). It
29	//! exists to make one specific bug visible: a kernel copy loop that failed to
30	//! advance would map 256 pages of *block 0*, and every header check would still
31	//! pass. Reading a different label from the far end is what distinguishes "the
32	//! blob was copied" from "the blob's first page was copied 256 times".
33	//!
34	//! Both labels are 16 bytes and differ from each other, so a 32-byte read of
35	//! either end is self-identifying.
36	
37	use crate::callnr::BDEV_BLOCK_SIZE;
38	use crate::uspace::RAMDISK_WINDOW_SIZE;
39	
40	/// Blocks in the root filesystem image: 256 × 4 KiB = 1 MiB.
41	///
42	/// **Fixed, not derived from the content.** When the musl sysroot is absent
43	/// `kernel/build.rs` packs the 15 KB `worker` ELF under the name `hello`, so a
44	/// content-sized image would make every size-derived boot marker
45	/// config-dependent — the slice-5.5/5.6 "right in one config, vacuous in the
46	/// other" trap. An image that outgrows this is a *build* failure naming this
47	/// constant (`MkfsError::TooBig`), with a one-constant fix.
48	pub const ROOTFS_IMAGE_BLOCKS: u32 = 256;
49	
50	/// Inodes in the root filesystem image. 64 is exactly one inode-table block, and
51	/// far more than the handful of files slices 5.7–5.9 put in the image.
52	pub const ROOTFS_NINODES: u32 = 64;
53	
54	/// Size of the root filesystem image in bytes.
55	pub const ROOTFS_IMAGE_BYTES: usize = ROOTFS_IMAGE_BLOCKS as usize * BDEV_BLOCK_SIZE;
56	
57	/// The reserved last block, which holds [`IMAGE_TAIL_LABEL`].
58	pub const ROOTFS_TAIL_BLOCK: u32 = ROOTFS_IMAGE_BLOCKS - 1;
59	
60	/// Bytes of image header at the start of block 0.
61	pub const IMAGE_HDR_LEN: usize = 32;
62	
63	/// Label at the start of the image. NUL-padded to [`IMAGE_LABEL_LEN`].
64	pub const IMAGE_LABEL: [u8; IMAGE_LABEL_LEN] = *b"minix.rs rootfs\0";
65	
66	/// Label at the start of the reserved last block. Deliberately different from
67	/// [`IMAGE_LABEL`] — that difference is the whole proof (see the module docs).
68	pub const IMAGE_TAIL_LABEL: [u8; IMAGE_LABEL_LEN] = *b"minix.rs tailv1\0";
69	
70	/// Length of each label.
71	pub const IMAGE_LABEL_LEN: usize = 16;
72	
73	/// Offset of the label within the header (and within the tail block).
74	pub const HDR_LABEL_OFF: usize = 0;
75	/// Offset of the image's block count within the header (u32).
76	pub const HDR_BLOCKS_OFF: usize = 16;
77	/// Offset of the image's block size within the header (u32).
78	pub const HDR_BLOCK_SIZE_OFF: usize = 20;
79	/// Offset of the MinixFS magic within the header (i32, sign-extended from the
80	/// superblock's `s_magic`). The one format fact a device-level check may look at:
81	/// it says "a filesystem was written here", not what its geometry is.
82	pub const HDR_MFS_MAGIC_OFF: usize = 24;
83	
84	// The header tiles exactly, with the trailing bytes reserved (written as zero).
85	const _: () = assert!(HDR_LABEL_OFF + IMAGE_LABEL_LEN == HDR_BLOCKS_OFF);
86	const _: () = assert!(HDR_BLOCKS_OFF + 4 == HDR_BLOCK_SIZE_OFF);
87	const _: () = assert!(HDR_BLOCK_SIZE_OFF + 4 == HDR_MFS_MAGIC_OFF);
88	const _: () = assert!(HDR_MFS_MAGIC_OFF + 4 <= IMAGE_HDR_LEN);
89	
90	// The header must fit inside MinixFS's boot block (bytes 0..1024 of block 0),
91	// which the filesystem never reads. Overrunning it would overwrite the superblock.
92	const _: () = assert!(IMAGE_HDR_LEN <= 1024);
93	
94	// A whole image must fit the VA window the kernel reserves for it, or the kernel's
95	// pre-map loop would run off the end of the window.
96	const _: () = assert!(ROOTFS_IMAGE_BYTES as u64 <= RAMDISK_WINDOW_SIZE);
97	// ...and it must be a whole number of blocks, which it is by construction — but
98	// the driver's geometry check leans on it, so state it.
99	const _: () = assert!(ROOTFS_IMAGE_BYTES.is_multiple_of(BDEV_BLOCK_SIZE));
100	const _: () = assert!(ROOTFS_IMAGE_BLOCKS > 0);
101	
102	#[cfg(test)]
103	mod tests {
104	    use super::*;
105	
106	    #[test]
107	    fn the_image_is_one_mebibyte_of_four_kib_blocks() {
108	        assert_eq!(ROOTFS_IMAGE_BLOCKS, 256);
109	        assert_eq!(ROOTFS_IMAGE_BYTES, 1024 * 1024);
110	        assert_eq!(ROOTFS_IMAGE_BYTES / BDEV_BLOCK_SIZE, 256);
111	        assert_eq!(ROOTFS_TAIL_BLOCK, 255);
112	        // The `[ramdisk] … len=1048576 pages=256` boot marker is these numbers.
113	        assert_eq!(ROOTFS_IMAGE_BYTES / 4096, 256);
114	    }
115	
116	    #[test]
117	    fn the_two_labels_differ() {
118	        // Head and tail must be distinguishable, or a copy loop that never
119	        // advanced would pass both probes.
120	        assert_ne!(IMAGE_LABEL, IMAGE_TAIL_LABEL);
121	        assert_eq!(IMAGE_LABEL.len(), IMAGE_LABEL_LEN);
122	        assert_eq!(IMAGE_TAIL_LABEL.len(), IMAGE_LABEL_LEN);
123	    }
124	
125	    #[test]
126	    fn each_label_is_nul_padded_and_not_full() {
127	        // A trailing NUL means the label reads as a C string too, which is what
128	        // makes it greppable in a hexdump without a length.
129	        for label in [IMAGE_LABEL, IMAGE_TAIL_LABEL] {
130	            assert_eq!(*label.last().unwrap(), 0);
131	            assert!(label.iter().any(|&b| b != 0));
132	        }
133	    }
134	
135	    #[test]
136	    fn the_header_fields_are_ordered_and_fit_the_boot_block() {
137	        let fields = [
138	            ("label", HDR_LABEL_OFF, IMAGE_LABEL_LEN),
139	            ("blocks", HDR_BLOCKS_OFF, 4),
140	            ("block_size", HDR_BLOCK_SIZE_OFF, 4),
141	            ("mfs_magic", HDR_MFS_MAGIC_OFF, 4),
142	        ];
143	        for pair in fields.windows(2) {
144	            let (name, off, width) = pair[0];
145	            let (next_name, next_off, _) = pair[1];
146	            assert!(
147	                off + width <= next_off,
148	                "{name} ({off}..{}) overlaps {next_name} at {next_off}",
149	                off + width
150	            );
151	        }
152	        let (_, last_off, last_width) = fields[fields.len() - 1];
153	        assert!(last_off + last_width <= IMAGE_HDR_LEN);
154	        // MinixFS's superblock starts at byte 1024; the header must not reach it.
155	        assert_eq!(IMAGE_HDR_LEN.min(1024), IMAGE_HDR_LEN);
156	    }
157	
158	    #[test]
159	    fn the_image_fits_the_ramdisk_window() {
160	        assert_eq!(
161	            (ROOTFS_IMAGE_BYTES as u64).min(RAMDISK_WINDOW_SIZE),
162	            ROOTFS_IMAGE_BYTES as u64,
163	            "the image does not fit the VA window reserved for it"
164	        );
165	    }
166	}
