3	//! minix.rs `init` — PID 1, the first user process (slice 4.8).
4	//!
5	//! Unlike the demo stubs it replaces, `init` is a real boot module: it is packed
6	//! into the boot-image archive with its true proc number (`INIT_PROC_NR = 10`)
7	//! and loaded + made runnable by the ordinary boot loop
8	//! (`kernel/src/arch/aarch64/userland.rs`), not hand-released by PM. It runs as
9	//! an ordinary user process — the shared `USER_PRIV_ID` privilege (SENDREC to PM
10	//! and VFS, and no kernel calls at all) — so the whole process lifecycle flows
11	//! through PM, and every byte of output through VFS, in the POSIX shape
12	//! (user → server, never user → kernel).
13	//!
14	//! `init` is the live exercise for the Phase-4 process machinery that the
15	//! slice-4.6/4.7 stub E demonstrated: it forks a child, the child execs a
16	//! boot-image binary, and the parent `wait`s to reap the zombie before looping
17	//! to fork again. Each cycle recycles the same fork-pool slot with an advancing
18	//! endpoint generation — observable in the boot trace as `SYS_FORK` /
19	//! `SYS_EXEC` / `SYS_EXIT` triples.
20	//!
21	//! Slice 5.6 makes the exec target the *caller's* choice — `PM_EXEC` carries a
22	//! name now, instead of PM hardcoding one — and init alternates between
23	//! [`EXEC_TARGETS`]: `worker` (5.5's exec-stack probe) and `hello` (the first C
24	//! program on minix.rs). Alternating keeps both proofs live; switching outright
25	//! would have retired the exec-ABI markers to make room for the C ones.
26	//!
27	//! Slice 5.4 gives it a voice. Before the fork loop it writes to **fd 1 and fd
28	//! 2** through VFS, which grants the buffer on to the TTY driver — the POSIX
29	//! write path, end to end, from an ordinary user process. init has no debug
30	//! channel of its own (`SYS_DIAGCTL` is a kernel call, and a user proc holds
31	//! none), so it reports *through the path under test*: if the path regresses the
32	//! lines change or vanish, and the boot markers go with them. See [`announce`].
33	//!
34	//! Slice 5.5 gives it one more thing to say. `SYS_EXEC` now hands a new image a
35	//! SysV initial stack, and `worker` checks that frame against its own `sp` and
36	//! encodes the verdict as its exit status — so init, which reaps it anyway,
37	//! prints the **first** such status and nothing thereafter. See
38	//! [`report_exec_stack`].
39	//!
40	//! Built as a freestanding aarch64 ELF (`userland/init/user.ld`). It uses
41	//! `minixrs-ipc` directly — no `server-rt`/SEF, because it is a plain user program,
42	//! not a server. The `_start` shim and panic handler are gated to `not(test)`.
43	
44	#![cfg_attr(not(test), no_std)]
45	#![cfg_attr(not(test), no_main)]
46	
47	minixrs_abi_note::brand!();
48	
49	use minixrs_ipc::ipc_sendrec;
50	use minixrs_kernel_shared::Message;
51	use minixrs_kernel_shared::callnr::{
52	    CDEV_MAX_IO, EXEC_NAME_LEN, PM_EXEC, PM_EXEC_NAME_OFF, PM_FORK, PM_WAIT, VFS_BUF_OFF,
53	    VFS_FD_OFF, VFS_LEN_OFF, VFS_WRITE,
54	};
55	use minixrs_kernel_shared::com::{PM_PROC_NR, VFS_PROC_NR, boot_endpoint};
56	use minixrs_kernel_shared::endpoint::Endpoint;
57	use minixrs_kernel_shared::error::{EBADF, EFAULT, EINVAL, ENOSYS, OK};
58	use minixrs_kernel_shared::execstack::EXEC_STACK_PROBE_PASS;
59	use minixrs_kernel_shared::message::USER_VA_TOP;
60	use minixrs_kernel_shared::uspace::USER_DEVICE_WINDOW_BASE;
61	
62	/// The boot loader primes `SP_EL0` before `eret`, so `_start` can dive straight
63	/// into Rust without setting up a stack itself.
64	#[cfg(not(test))]
65	#[unsafe(no_mangle)]
66	#[cfg_attr(target_os = "minixrs", unsafe(link_section = ".text._start"))]
67	pub extern "C" fn _start() -> ! {
68	    main()
69	}
70	
71	/// Standard output, pre-opened by VFS to the console — POSIX's inheritance
72	/// convention, which is what lets init write before any filesystem exists.
73	const STDOUT: i32 = 1;
74	/// Standard error, also the console. Used for the denial summary specifically so
75	/// that line proves fd 2 resolves as well as fd 1.
76	const STDERR: i32 = 2;
77	
78	/// The milestone line: the first bytes an ordinary user process ever put on the
79	/// console under its own POSIX call.
80	const HELLO: &str = "minix.rs init: hello via VFS write\n";
81	
82	/// A line long enough that no single `CDEV_WRITE` can carry it, so VFS must loop.
83	///
84	/// Sized from [`CDEV_MAX_IO`] — the driver's staging limit — even though a user
85	/// process has no business knowing that number: reading it here is what keeps the
86	/// probe *meaningful* if the limit ever moves, instead of silently degrading into
87	/// a line that fits in one transfer. That the constant is invisible in `write()`'s
88	/// result is the property under test.
89	const LOOP_LINE_LEN: usize = CDEV_MAX_IO + 32;
90	
91	/// The line itself: a rule of dashes ending in a marker that only reaches the
92	/// console if VFS re-sent with `offset` advanced. Without the loop the console
93	/// gets the first [`CDEV_MAX_IO`] bytes and `vfs-loop-end` is never printed.
94	static LOOP_LINE: [u8; LOOP_LINE_LEN] = loop_line_pattern();
95	
96	const fn loop_line_pattern() -> [u8; LOOP_LINE_LEN] {
97	    let mut b = [b'-'; LOOP_LINE_LEN];
98	    let prefix = b"minix.rs init: vfs long write ";
99	    let mut i = 0;
100	    while i < prefix.len() {
101	        b[i] = prefix[i];
102	        i += 1;
103	    }
104	    // The tail sits at the very end, past the clamp, and ends the line.
105	    let tail = b"vfs-loop-end\n";
106	    let base = LOOP_LINE_LEN - tail.len();
107	    let mut j = 0;
108	    while j < tail.len() {
109	        b[base + j] = tail[j];
110	        j += 1;
111	    }
112	    b
113	}
114	
115	const _: () = assert!(LOOP_LINE_LEN > CDEV_MAX_IO);
116	
117	/// A virtual address that is **not** mapped in init's address space, for the
118	/// `EFAULT` probe.
119	///
120	/// init's image is linked at `0x0010_0000` (`user.ld`) and the kernel maps it a
121	/// single stack page at `0x0020_0000`, so `0x0030_0000` is a hole. It costs init
122	/// no page fault: the kernel's copy engine *walks* the page tables and answers
123	/// `EFAULT` (D5) rather than dereferencing, so this probe cannot SIGSEGV the
124	/// process making it.
125	///
126	/// The probe only proves what it claims if the address is well-formed enough to
127	/// reach the page-table walk — an address VFS's own `user_range_ok` pre-check
128	/// rejected would answer `EFAULT` one hop earlier and silently test the wrong
129	/// thing. The guards below pin exactly that: non-NULL and below `USER_VA_TOP`, so
130	/// every range check on the way down passes, and clear of the kernel's device
131	/// window, which *is* mapped in some address spaces. The two layout facts it also
132	/// depends on — the link base and the stack VA — stay prose, because neither is a
133	/// shared constant a user program can see.
134	const UNMAPPED_VA: u64 = 0x0030_0000;
135	
136	const _: () = assert!(UNMAPPED_VA != 0);
137	const _: () = assert!(UNMAPPED_VA < USER_VA_TOP);
138	const _: () = assert!(UNMAPPED_VA < USER_DEVICE_WINDOW_BASE);
139	
140	/// The boot-image modules `init` execs, in rotation — one per fork cycle.
141	///
142	/// **`worker` must stay first.** It is slice 5.5's exec-stack probe, and the
143	/// verdict is keyed on the *first* child's pid ([`main`]'s `probe_pid`), so
144	/// reordering this array silently retires the `exec stack ok` marker while
145	/// leaving every other marker in place.
146	///
147	/// Alternating rather than switching outright is the whole point: `hello` is the
148	/// slice-5.6 C milestone, but retiring `worker` to make room would take the
149	/// exec-ABI proof down with it. Both traces land inside the `[ksys SYS_EXEC]`
150	/// head carve-out (6 calls), so both are observable in a boot log.
151	const EXEC_TARGETS: [&str; 2] = ["worker", "hello"];
152	
153	// Each name has to fit the `PM_EXEC` payload field, which is the same width as
154	// the kernel's `SYS_EXEC` field — so a name that fits here forwards uncut.
155	const _: () = {
156	    let mut i = 0;
157	    while i < EXEC_TARGETS.len() {
158	        assert!(!EXEC_TARGETS[i].is_empty(), "an empty name is EINVAL");
159	        assert!(EXEC_TARGETS[i].len() <= EXEC_NAME_LEN);
160	        i += 1;
161	    }
162	};
163	
164	/// Build a request message to PM: no payload, `m_source` is stamped by the kernel.
165	#[cfg_attr(test, allow(dead_code))]
166	fn pm_msg(m_type: i32) -> Message {
167	    Message {
168	        m_source: 0,
169	        m_type,
170	        payload: [0u8; 96],
171	    }
172	}
173	
174	#[cfg_attr(test, allow(dead_code))]
175	fn main() -> ! {
176	    let pm = boot_endpoint(PM_PROC_NR);
177	    // By boot endpoint, not through DS: init's privilege opens `ipc_to` to PM and
178	    // VFS alone, so it could not ask DS even if it wanted to. That is the point of
179	    // the user grade — a user process talks to servers, not to the registry.
180	    let vfs = boot_endpoint(VFS_PROC_NR);
181	
182	    announce(vfs);
183	
184	    // One-shot: the exec-ABI verdict of the first child init forks (slice 5.5).
185	    //
186	    // Keyed on that child's **pid**, not on "the first reap", because the two are
187	    // not the same reap. PM seeds the demo stubs as init's children, and stub D
188	    // is SIGSEGV'd on purpose early in boot — so init's first `wait()` returns
189	    // that zombie, whose status has nothing to do with exec and happens to be 0.
190	    // Reporting it would print `exec stack ok` no matter what the frame looked
191	    // like. `alloc_pid` never hands out 0, so it doubles as the "not yet" value.
192	    let mut probe_pid = 0;
193	    let mut reported = false;
194	    let mut cycle = 0usize;
195	
196	    loop {
197	        // Chosen *before* the fork, so both halves of the SENDREC agree on it:
198	        // the child is a copy of this address space taken during `SYS_FORK`, so
199	        // it inherits this value and needs no way to ask which turn it is. The
200	        // parent advances `cycle` only after a successful fork.
201	        let target = EXEC_TARGETS[cycle % EXEC_TARGETS.len()];
202	
203	        // fork(): PM replies to both halves of this SENDREC — the child sees
204	        // `m_type == 0`, the parent sees the child pid (`> 0`); a negative value
205	        // is an errno (e.g. `EAGAIN` when the fork table is full).
206	        let mut m = pm_msg(PM_FORK);
207	        let _ = ipc_sendrec(pm, &mut m);
208	
209	        match m.m_type {
210	            0 => {
211	                // Child: replace this image with `target`. PM issues `SYS_EXEC`
212	                // and the kernel resumes us at the new image's `_start`, so this
213	                // SENDREC never returns on success.
214	                let mut e = pm_msg(PM_EXEC);
215	                let bytes = target.as_bytes();
216	                e.payload[PM_EXEC_NAME_OFF..PM_EXEC_NAME_OFF + bytes.len()].copy_from_slice(bytes);
217	                let _ = ipc_sendrec(pm, &mut e);
218	                // Unreachable on success; park defensively if exec ever failed.
219	                loop {
220	                    core::hint::spin_loop()
221	                }
222	            }
223	            n if n > 0 => {
224	                cycle = cycle.wrapping_add(1);
225	                // Parent: `n` is the new child's pid. Remember the first one —
226	                // that is the process whose exec-ABI verdict gets reported.
227	                if probe_pid == 0 {
228	                    probe_pid = n;
229	                }
230	                // Reap a child (blocks until one exits), then loop to fork the
231	                // next. `wait()` replies the reaped child's pid, so the verdict
232	                // is reported only when the child that ran `worker` comes back —
233	                // and only once, since the loop runs forever and a line per
234	                // cycle would bury the console.
235	                let mut w = pm_msg(PM_WAIT);
236	                let rc = ipc_sendrec(pm, &mut w);
237	                if !reported && rc == OK && w.m_type == probe_pid {
238	                    reported = true;
239	                    report_exec_stack(vfs, rd_i32(&w, 0));
240	                }
241	            }
242	            _ => {
243	                // Transient fork failure (table full): back off briefly, retry.
244	                for _ in 0..1024 {
245	                    core::hint::spin_loop()
246	                }
247	            }
248	        }
249	    }
250	}
251	
252	/// Exercise the slice-5.4 write path, and report the result over it.
253	///
254	/// Three things go to the console, in order:
255	///
256	/// 1. **The banner** ([`HELLO`], fd 1) — the milestone. A user process, holding no
257	///    kernel calls and no grant table of its own, put bytes on the console by
258	///    calling `write`.
259	/// 2. **A line longer than one `CDEV_WRITE`** ([`LOOP_LINE`], fd 1), and the
260	///    *count* it returned. Two independent halves of the same contract: the tail
261	///    marker appears only if VFS re-sent with `offset` advanced, and `match=1`
262	///    says VFS reported the whole buffer rather than the driver's clamp. Neither
263	///    subsumes the other — a `write()` that moved every byte but returned `OK`
264	///    would print the tail and still be broken, which is exactly the bug a caller
265	///    looping on a short write would then hit forever.
266	/// 3. **Three denial probes and a summary** (fd 2, so that descriptor is proven
267	///    too). Each probe is well-formed in every respect but one — the slice-5.1
268	///    lesson that a check no marker exercises is a check that can regress
269	///    silently.
270	///
271	/// `match=1` rather than the length itself, the slice-5.3 convention: it is
272	/// self-checking, needs no formatting machinery (init has none), and does not have
273	/// to be re-derived when the line's length changes.
274	///
275	/// Best-effort: init's job is to keep the system running, so a failure here is
276	/// reported and stepped over, never fatal.
277	#[cfg_attr(test, allow(dead_code))]
278	fn announce(vfs: Endpoint) {
279	    let _ = vfs_write(vfs, STDOUT, HELLO.as_bytes());
280	
281	    let rc = vfs_write(vfs, STDOUT, &LOOP_LINE);
282	    let verdict = if rc == LOOP_LINE_LEN as i32 {
283	        "minix.rs init: vfs.long ok match=1\n"
284	    } else {
285	        "minix.rs init: vfs.long FAIL\n"
286	    };
287	    let _ = vfs_write(vfs, STDOUT, verdict.as_bytes());
288	
289	    deny_probes(vfs);
290	}
291	
292	/// The `VFS_WRITE` requests that must be refused, each valid but for one field.
293	///
294	///   - `bad-fd` — a perfectly good buffer written to descriptor 3, which is in
295	///     range of the fd row but not open. `EBADF`, from VFS's fd table; make the
296	///     table accept any descriptor and this write *succeeds*.
297	///   - `no-such` — a request number one past `VFS_WRITE`. `ENOSYS`, from VFS's
298	///     dispatch — and the reply itself is the assertion: a server that dropped an
299	///     unknown request instead of replying would leave init blocked here forever,
300	///     taking the whole boot with it.
301	///   - `bad-buf` — an unmapped buffer ([`UNMAPPED_VA`]). `EFAULT`, from the
302	///     kernel's page-table walk in the middle of TTY's safecopy, relayed back out
303	///     through the driver and VFS unchanged. It proves the errno survives two
304	///     hops without being flattened into a generic failure.
305	///   - `bad-len` — a negative byte count. `EINVAL`, and the check matters more
306	///     than it looks: left unchecked the length widens into a ~16 EiB `u64` on the
307	///     grant VFS is about to issue over the caller's buffer.
308	///
309	/// The one arm with no probe here is a **zero**-length write, which is a legal
310	/// no-op rather than a denial and would need a distinct positive marker to say
311	/// anything. `write::validate` covers it — and the fact that it is checked before
312	/// the buffer, so a zero-length write never issues a grant — in host tests.
313	#[cfg_attr(test, allow(dead_code))]
314	fn deny_probes(vfs: Endpoint) {
315	    let addr = HELLO.as_ptr() as usize as u64;
316	    let len = HELLO.len() as i32;
317	
318	    // (name, request, fd, buffer, length, expected reply)
319	    let probes: [(&str, i32, i32, u64, i32, i32); 4] = [
320	        ("bad-fd", VFS_WRITE, 3, addr, len, EBADF),
321	        ("no-such", VFS_WRITE + 1, STDOUT, addr, len, ENOSYS),
322	        ("bad-buf", VFS_WRITE, STDOUT, UNMAPPED_VA, len, EFAULT),
323	        ("bad-len", VFS_WRITE, STDOUT, addr, -1, EINVAL),
324	    ];
325	
326	    for (name, m_type, fd, buf, len, want) in probes {
327	        if vfs_request(vfs, m_type, fd, buf, len) != want {
328	            return report_fail(vfs, name);
329	        }
330	    }
331	    let _ = vfs_write(vfs, STDERR, "minix.rs init: vfs.deny ok n=4\n".as_bytes());
332	}
333	
334	/// Report the first failing probe by name, on fd 2.
335	///
336	/// Hand-assembled into a stack buffer: init has no formatting runtime (no
337	/// `server-rt`, so no `diag_fmt`), and the buffer's address is what VFS grants on
338	/// to the driver — legal because init stays blocked in the SENDREC for the whole
339	/// copy, so the frame outlives every use of it.
340	#[cfg_attr(test, allow(dead_code))]
341	fn report_fail(vfs: Endpoint, name: &str) {
342	    let mut line = [0u8; 64];
343	    let mut n = append(&mut line, 0, b"minix.rs init: vfs.deny FAIL ");
344	    n = append(&mut line, n, name.as_bytes());
