349	/// Report the exec-ABI verdict the first reaped child carried out (slice 5.5).
350	///
351	/// `worker` reads its own `sp` and checks the SysV initial stack `SYS_EXEC` built
352	/// — `argc`/`argv`/`envp`/auxv — then exits with `0` or the number of the first
353	/// failing check. That verdict has to leave the process somehow, and a console
354	/// line per fork cycle would flood the log, so it rides out as the exit status
355	/// and init prints it once. The kernel's own `[exec]` trace says only that the
356	/// kernel *thinks* it wrote a frame; this line is the EL0 half of the proof.
357	///
358	/// `status` is the `W_EXITCODE` PM encodes: the exit code sits in bits 8..16.
359	///
360	/// Success is a **positive sentinel**, not 0, because 0 is what a child that
361	/// never got as far as reporting leaves behind: PM's kill path marks a signalled
362	/// process a zombie without setting `exit_status`, so a worker that faulted on a
363	/// malformed frame — which VM turns into a SIGSEGV, not the unhandled EL0 abort
364	/// the forbidden list watches for — would otherwise be reaped as a pass. That
365	/// case gets its own `no-verdict` spelling so the log names it.
366	#[cfg_attr(test, allow(dead_code))]
367	fn report_exec_stack(vfs: Endpoint, status: i32) {
368	    let code = (status >> 8) & 0xff;
369	    if code == EXEC_STACK_PROBE_PASS {
370	        let _ = vfs_write(vfs, STDOUT, b"minix.rs init: exec stack ok\n");
371	        return;
372	    }
373	
374	    let mut line = [0u8; 64];
375	    let mut n = append(&mut line, 0, b"minix.rs init: exec stack FAIL ");
376	    if code == 0 {
377	        n = append(&mut line, n, b"no-verdict\n");
378	    } else {
379	        n = append(&mut line, n, b"code=");
380	        let mut digits = [0u8; 3];
381	        let mut d = 0;
382	        let mut v = code as u32;
383	        loop {
384	            digits[d] = b'0' + (v % 10) as u8;
385	            v /= 10;
386	            d += 1;
387	            if v == 0 || d == digits.len() {
388	                break;
389	            }
390	        }
391	        digits[..d].reverse();
392	        n = append(&mut line, n, &digits[..d]);
393	        n = append(&mut line, n, b"\n");
394	    }
395	    // fd 2, like init's other failure report and worker's own — failures go to
396	    // stderr, and it keeps that descriptor exercised on the path that matters.
397	    let _ = vfs_write(vfs, STDERR, &line[..n]);
398	}
