400	/// Append `src` to `line[..n]`, dropping any overflow, and return the new length.
401	///
402	/// The whole of init's string formatting: no allocator, no `core::fmt`, and a
403	/// truncating append rather than a fallible one, because a report that does not
404	/// quite fit is still worth printing.
405	#[cfg_attr(test, allow(dead_code))]
406	fn append(line: &mut [u8], mut n: usize, src: &[u8]) -> usize {
407	    for &b in src {
408	        if n < line.len() {
409	            line[n] = b;
410	            n += 1;
411	        }
412	    }
413	    n
414	}
