641	/// Build one user-space crate for the custom `aarch64-unknown-minixrs` target
642	/// (`tools/targets/aarch64-unknown-minixrs.json`, via `-Zbuild-std`) and return
643	/// the path to the produced ELF.
644	///
645	/// The `-T<user.ld>` link arg comes from each crate's own build.rs, cfg-gated
646	/// on `target_os = "minixrs"` — nothing is injected here. Inherited rustflags
647	/// are scrubbed instead, so the kernel's `-Tlinker.ld` (keyed on
648	/// `aarch64-unknown-none` in `.cargo/config.toml`, which the JSON target name
649	/// doesn't match anyway) or a developer's env can't leak in.
650	fn build_server(
651	    crate_name: &str,
652	    crate_dir: &std::path::Path,
653	    workspace: &std::path::Path,
654	    extra_args: &[&str],
655	) -> PathBuf {
656	    // One shared nested target dir (not per-crate): -Zbuild-std would otherwise
657	    // rebuild core+alloc 9x per kernel build. Nested invocations run
658	    // sequentially from this script; cargo's own locking covers any overlap
659	    // with developer commands. Still separate from the outer `target/` root,
660	    // so nesting cargo here cannot deadlock on the kernel build's lock.
661	    let target_dir = workspace.join("target/minixrs-user");
662	    let target_json = workspace.join("tools/targets/aarch64-unknown-minixrs.json");
663	
664	    // Rebuild + re-embed whenever this server's sources, linker script, manifest,
665	    // or own build script change. `src` is watched as a directory so submodules
666	    // (e.g. `servers/ds/src/registry.rs`) are covered — watching only `main.rs`
667	    // would silently embed a stale ELF after a submodule edit. `build.rs` is
668	    // watched because it emits the crate's `-T<user.ld>` link arg (M1): cargo
669	    // reruns the *nested* build for it, but only this line makes the *outer*
670	    // kernel build notice and re-pack.
671	    for path in [
672	        crate_dir.join("src"),
673	        crate_dir.join("user.ld"),
674	        crate_dir.join("Cargo.toml"),
675	        crate_dir.join("build.rs"),
676	    ] {
677	        println!("cargo:rerun-if-changed={}", path.display());
678	    }
679	
680	    let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".into());
681	    let status = Command::new(cargo)
682	        .current_dir(workspace)
683	        .args(["build", "-p", crate_name, "--target"])
684	        .arg(&target_json)
685	        .args([
686	            "--release",
687	            // The pinned nightly gates `.json` target specs behind this flag.
688	            // It must be passed explicitly here: a developer's *global*
689	            // `~/.cargo/config.toml` may carry `[unstable] json-target-spec`
690	            // (RustRover needs it), which masks its absence locally while CI —
691	            // which has no such config — fails the nested build.
692	            "-Zjson-target-spec",
693	            // Custom target ⇒ no prebuilt core/alloc; `compiler-builtins-mem`
694	            // provides memcpy/memset (harmless if a future nightly defaults it).
695	            "-Zbuild-std=core,alloc",
696	            "-Zbuild-std-features=compiler-builtins-mem",
697	        ])
698	        .args(extra_args)
699	        .env("CARGO_TARGET_DIR", &target_dir)
700	        // The servers' -T<user.ld> now comes from each crate's own build.rs
701	        // (cfg-gated on target_os = "minixrs"); scrub any inherited rustflags
702	        // so the kernel's -Tlinker.ld (or a user's env) can't leak in.
703	        .env_remove("RUSTFLAGS")
704	        .env_remove("CARGO_ENCODED_RUSTFLAGS")
705	        .status()
706	        .unwrap_or_else(|e| panic!("failed to spawn cargo for {crate_name}: {e}"));
707	    if !status.success() {
708	        panic!("building {crate_name} (server ELF) failed");
709	    }
710	
711	    let elf = target_dir.join(format!("aarch64-unknown-minixrs/release/{crate_name}"));
712	    assert!(
713	        elf.exists(),
714	        "{crate_name} ELF missing at {}",
715	        elf.display()
716	    );
717	    elf
718	}
