720	/// Pack server ELFs into the minix.rs boot-image (MXBI) archive:
721	///
722	/// ```text
723	///   16-byte header: magic "MXBI" (LE u32), version, entry_count, total_size
724	///   entry_count × 32-byte records: { proc_nr:i32, offset:u32, len:u32, name:[u8;20] }
725	///   then the ELF payloads back-to-back, each at its recorded offset
726	/// ```
727	///
728	/// All multi-byte fields are little-endian (build host and aarch64 target are
729	/// both LE); `boot_image::BootImage` parses this with matching `from_le_bytes`.
730	fn pack_mxbi(modules: &[(i32, String, Vec<u8>)]) -> Vec<u8> {
731	    const MAGIC: u32 = 0x4942_584D; // "MXBI" as little-endian bytes M,X,B,I
732	    const VERSION: u32 = 1;
733	    const HDR_LEN: usize = 16;
734	    const REC_LEN: usize = 32;
735	    const NAME_LEN: usize = 20;
736	
737	    let n = modules.len();
738	    let payload_start = HDR_LEN + n * REC_LEN;
739	
740	    // Build the record table, assigning each payload an offset past the table.
741	    let mut offset = payload_start;
742	    let mut records = Vec::with_capacity(n * REC_LEN);
743	    for (proc_nr, name, bytes) in modules {
744	        let name_bytes = name.as_bytes();
745	        assert!(
746	            name_bytes.len() < NAME_LEN,
747	            "server name {name:?} too long for MXBI {NAME_LEN}-byte name field"
748	        );
749	        // The record's offset and length are u32 on the wire. These casts were
750	        // unchecked until slice 5.7 added a 1 MiB non-ELF blob to the archive —
751	        // the same latent-cast class the workspace's `checked_add` convention
752	        // exists to kill. A silent truncation here would produce an archive whose
753	        // table points into the middle of a payload.
754	        assert!(
755	            bytes.len() <= u32::MAX as usize,
756	            "MXBI module {name:?} is {} bytes, past the u32 length field",
757	            bytes.len()
758	        );
759	        assert!(
760	            offset <= u32::MAX as usize,
761	            "MXBI archive exceeds the u32 offset field at module {name:?}"
762	        );
763	        records.extend_from_slice(&proc_nr.to_le_bytes());
764	        records.extend_from_slice(&(offset as u32).to_le_bytes());
765	        records.extend_from_slice(&(bytes.len() as u32).to_le_bytes());
766	        let mut name_field = [0u8; NAME_LEN];
767	        name_field[..name_bytes.len()].copy_from_slice(name_bytes);
768	        records.extend_from_slice(&name_field);
769	        offset += bytes.len();
770	    }
771	    // The loop checks `offset` *before* adding the module's length, so the final
772	    // total is the one value it cannot have covered: the last module may start
773	    // inside the u32 range and end past it. `total_size` is itself a u32 header
774	    // field, so check it here or the cast below truncates the archive's own
775	    // recorded size while every per-record assert passes.
776	    assert!(
777	        offset <= u32::MAX as usize,
778	        "MXBI archive is {offset} bytes, past the u32 total-size field"
779	    );
780	    let total_size = offset;
781	
782	    let mut archive = Vec::with_capacity(total_size);
783	    archive.extend_from_slice(&MAGIC.to_le_bytes());
784	    archive.extend_from_slice(&VERSION.to_le_bytes());
785	    archive.extend_from_slice(&(n as u32).to_le_bytes());
786	    archive.extend_from_slice(&(total_size as u32).to_le_bytes());
787	    archive.extend_from_slice(&records);
788	    for (_, _, bytes) in modules {
789	        archive.extend_from_slice(bytes);
790	    }
791	    assert_eq!(archive.len(), total_size, "MXBI archive size mismatch");
792	    archive
793	}
