        root: rd_i32(&m, FS_SUPER_ROOT_OFF),
        block_size: rd_i32(&m, FS_SUPER_BLOCK_SIZE_OFF),
        blocks: rd_i32(&m, FS_SUPER_BLOCKS_OFF),
